// Generate a random 128-bit id value
sd_id128_t id = *FUZZ_PARAM(sd_id128_t);

// Buffer must have at least 33 bytes (32 hex chars + NUL)
char buf[33];

// Call target: converts id to lowercase hex without separators
char *ret = sd_id128_to_string(id, buf);

// Validate API contract: returned pointer aliases the provided buffer
FUZZ_ASSERT(ret == buf, "sd_id128_to_string must return the provided buffer pointer");

// Ensure NUL termination at the documented position
FUZZ_ASSERT(buf[32] == '\0', "sd_id128_to_string must NUL-terminate at index 32");

// Light sanity: characters before NUL should be hex digits (case-insensitive acceptable; spec says lowercase)
for (int i = 0; i < 32; i++) {
    char c = buf[i];
    if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
        FUZZ_BAIL();
    }
}

// Generate a random 128-bit id value
sd_id128_t id = *FUZZ_PARAM(sd_id128_t);

// Buffer must have at least 37 bytes (36 chars + NUL)
char buf[37];

// Call target: converts id to UUID-style string 8-4-4-4-12
char *ret = sd_id128_to_uuid_string(id, buf);

// Validate returned pointer and NUL
FUZZ_ASSERT(ret == buf, "sd_id128_to_uuid_string must return the provided buffer pointer");
FUZZ_ASSERT(buf[36] == '\0', "sd_id128_to_uuid_string must NUL-terminate at index 36");

// Basic format check: dashes at positions 8,13,18,23
if (!(buf[8] == '-' && buf[13] == '-' && buf[18] == '-' && buf[23] == '-')) {
    FUZZ_BAIL();
}

// Hex digits in all other positions
for (int i = 0; i < 36; i++) {
    if (i == 8 || i == 13 || i == 18 || i == 23) continue;
    char c = buf[i];
    if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
        FUZZ_BAIL();
    }
}

// Generate an input string; may be random garbage or valid hex/UUID
std::string s = FUZZ_PARAM_STR();

// Ensure it is NUL-terminated when passing to API
const char *c = s.c_str();

// Prepare output holder
sd_id128_t out{};

// Call target
int r = sd_id128_from_string(c, &out);

// Contract checks: ret pointer must be non-NULL (we provided a valid address). We only assert that
// the function returns 0 on success; on failure, it may return negative errno. We accept both paths.
if (r == 0) {
    // On success, stringify back and parse again to check stability
    char hexbuf[33];
    sd_id128_to_string(out, hexbuf);
    sd_id128_t out2{};
    int r2 = sd_id128_from_string(hexbuf, &out2);
    FUZZ_ASSERT(r2 == 0, "Parsing a freshly stringified ID must succeed");
}

// Prepare output holder
sd_id128_t id{};

// Call target
int r = sd_id128_randomize(&id);

// Accept both success and failure as per API; if success, ensure it's not the NULL-id too often
if (r == 0) {
    // Basic non-NULL sanity: allow rare all-zero, but bail occasionally to steer fuzzer
    int all_zero = 1;
    for (int i = 0; i < 16; i++) if (id.bytes[i] != 0) { all_zero = 0; break; }
    if (all_zero) { FUZZ_BAIL(); }
}

sd_id128_t id{};
int r = sd_id128_get_machine(&id);
// On success, ensure stringification works
if (r == 0) {
    char buf[33];
    char *p = sd_id128_to_string(id, buf);
    FUZZ_ASSERT(p == buf, "to_string must return provided buffer");
}

sd_id128_t id{};
int r = sd_id128_get_boot(&id);
if (r == 0) {
    // UUID formatting should also work
    char buf[37];
    char *p = sd_id128_to_uuid_string(id, buf);
    FUZZ_ASSERT(p == buf, "to_uuid_string must return provided buffer");
}

sd_id128_t id{};
