sd_id128_t a = *FUZZ_PARAM(sd_id128_t);
sd_id128_t b = *FUZZ_PARAM(sd_id128_t);

// Target: value equality predicate
int ab = sd_id128_equal(a, b);

// Reflexivity: a must equal itself
int aa = sd_id128_equal(a, a);
FUZZ_ASSERT(aa != 0, "sd_id128_equal must be reflexive");

// Symmetry: if a==b then b==a
int ba = sd_id128_equal(b, a);
if (ab) FUZZ_ASSERT(ba != 0, "sd_id128_equal must be symmetric on equality");

// Build an sd_id128 value and two possible strings: matching and random
sd_id128_t id = *FUZZ_PARAM(sd_id128_t);
char good[33];
sd_id128_to_string(id, good);
std::string rnd = FUZZ_PARAM_STR();

// Randomly choose path to exercise both equality and inequality
unsigned int pick = *FUZZ_PARAM(unsigned int);
const char *s = (pick & 1) ? good : rnd.c_str();
int eq = sd_id128_string_equal(s, id);

// If we passed canonical hex, it must be equal; otherwise accept either (parser may accept rnd)
if (s == good) {
    FUZZ_ASSERT(eq != 0, "sd_id128_string_equal must report equality for canonical hex");
}

sd_id128_t a = *FUZZ_PARAM(sd_id128_t);
