}

// Property: if we ensure presence of 'a' explicitly, result must be true. Re-run with 'a' included once.
int found2 = sd_id128_in_set_sentinel(a, a, null_id);
FUZZ_ASSERT(found2 != 0, "in_set_sentinel must return true when the first variadic arg equals 'a'");

// sd_listen_fds: exercise with unset_environment randomly 0/1.
// We don't rely on the environment being present; valid behavior is often 0 (no fds).
int unset_environment = (int)(*FUZZ_PARAM(unsigned int) & 1u);
