int r = sd_is_socket(fd, q_family, q_type, listening);
close(fd);
if (r < 0) { FUZZ_BAIL(); }
// Validation: fd is valid, parameters honor API skipping semantics; negative return indicates hard error and we bail.

// Create an INET/INET6 socket; avoid sockaddr_* types by not binding; skip port check.
