int family = is_v6 ? AF_INET6 : AF_INET;
int type = ((*FUZZ_PARAM(unsigned int) & 1u) ? SOCK_STREAM : SOCK_DGRAM);
int fd = socket(family, type, 0);
if (fd < 0) { FUZZ_BAIL(); }
int listened = 0;
if (type == SOCK_STREAM) {
    if (listen(fd, 1) == 0) listened = 1; // may succeed without explicit bind
}
int q_family = ((*FUZZ_PARAM(unsigned int) & 1u) ? family : 0);
