import random
import string
from typing import List

# Systemd notify state generator
# Produces a newline-separated list of KEY=VALUE lines, NUL-terminated by caller usage.
# Valid keys per sd_notify protocol. We'll include a mix to trigger different code paths
# while keeping everything valid ASCII and under 4096 bytes.

_MAX_BYTES = 4096

# Common valid keys and value generators
_BASE_KEYS = [
    "READY", "STATUS", "MAINPID", "WATCHDOG", "WATCHDOG_USEC", "EXTEND_TIMEOUT_USEC",
    "ERRNO", "BUSERROR", "EXIT_STATUS", "RELOADING", "STOPPING", "SUCCESS",
    "FDSTORE", "FDNAME", "MONOTONIC_USEC", "WATCHDOG_PID", "INVOCATION_ID",
]

# Some environment-like extras accepted by sd_notify, commonly used by services
_EXTRA_KEYS = [
    "CPU_WEIGHT", "IO_WEIGHT", "MEMORY_CURRENT", "MEMORY_PEAK", "TASKS_CURRENT",
    "STATUS",  # allow repetition with different content
]

# Values
def _rand_bool01(rnd: random.Random) -> str:
    return "1" if rnd.choice([True, False]) else "0"

def _rand_decimal(rnd: random.Random, lo: int, hi: int) -> str:
    return str(rnd.randint(lo, hi))

def _rand_usec(rnd: random.Random, lo: int = 1_000, hi: int = 60_000_000) -> str:
    return _rand_decimal(rnd, lo, hi)

def _rand_pid(rnd: random.Random) -> str:
    # PID range: 1..2^22 typically, but keep modest
    return _rand_decimal(rnd, 1, 200000)

def _rand_errno(rnd: random.Random) -> str:
    # Common errno range
    return _rand_decimal(rnd, 0, 133)

def _rand_status(rnd: random.Random) -> str:
    # Construct concise but informative status lines
    parts = []
    verbs = ["Starting", "Running", "Processing", "Waiting", "Syncing", "Idle", "Shutting down"]
    objs = ["jobs", "requests", "tasks", "units", "connections", "events"]
    parts.append(rnd.choice(verbs))
    parts.append("%d" % rnd.randint(0, 10000))
    parts.append(rnd.choice(objs))
    # optional progress
    if rnd.random() < 0.6:
        parts.append("(%d%%)" % rnd.randint(0, 100))
    # optional extra note
    if rnd.random() < 0.5:
        parts.append("mode=" + rnd.choice(["normal", "degraded", "maintenance"]))
    s = " ".join(parts)
    # limit line lengths
    return s[:200]

def _rand_fdname(rnd: random.Random) -> str:
    # Per docs, a short identifier [A-Za-z0-9:_-.]
    alphabet = string.ascii_letters + string.digits + ":_- ."
    name = ''.join(rnd.choice(alphabet) for _ in range(rnd.randint(3, 16)))
    return name.strip()

def _rand_invocation_id(rnd: random.Random) -> str:
    # 128-bit hex (no dashes) or UUID format are both accepted
    if rnd.random() < 0.5:
        return ''.join(rnd.choice('0123456789abcdef') for _ in range(32))
    # UUID 8-4-4-4-12
    def hx(n):
        return ''.join(rnd.choice('0123456789abcdef') for _ in range(n))
    return f"{hx(8)}-{hx(4)}-{hx(4)}-{hx(4)}-{hx(12)}"

def _make_line(key: str, value: str) -> str:
    # Ensure no newlines inside values per sd_notify format
    value = value.replace('\n', ' ').replace('\r', ' ')
    return f"{key}={value}\n"

def _pick_base_lines(rnd: random.Random) -> List[str]:
    lines: List[str] = []

    # READY is commonly used, include often
    if rnd.random() < 0.9:
        lines.append(_make_line("READY", "1"))

    # STATUS
    lines.append(_make_line("STATUS", _rand_status(rnd)))

    # MAINPID or WATCHDOG_PID
    if rnd.random() < 0.8:
        lines.append(_make_line("MAINPID", _rand_pid(rnd)))
    elif rnd.random() < 0.5:
        lines.append(_make_line("WATCHDOG_PID", _rand_pid(rnd)))

    # WATCHDOG toggles
    if rnd.random() < 0.7:
        lines.append(_make_line("WATCHDOG", _rand_bool01(rnd)))
        lines.append(_make_line("WATCHDOG_USEC", _rand_usec(rnd)))

    # EXTEND_TIMEOUT_USEC sometimes
    if rnd.random() < 0.5:
        lines.append(_make_line("EXTEND_TIMEOUT_USEC", _rand_usec(rnd)))

    # Optional error codes
    if rnd.random() < 0.3:
        lines.append(_make_line("ERRNO", _rand_errno(rnd)))
    if rnd.random() < 0.2:
        lines.append(_make_line("EXIT_STATUS", _rand_decimal(rnd, 0, 255)))

    # RELOADING/STOPPING/SUCCESS lines
    if rnd.random() < 0.3:
        lines.append(_make_line("RELOADING", _rand_bool01(rnd)))
    if rnd.random() < 0.2:
        lines.append(_make_line("STOPPING", "1"))
    if rnd.random() < 0.3:
        lines.append(_make_line("SUCCESS", _rand_bool01(rnd)))

    # FD store usage
    if rnd.random() < 0.25:
        lines.append(_make_line("FDSTORE", _rand_bool01(rnd)))
        lines.append(_make_line("FDNAME", _rand_fdname(rnd)))

    # Invocation ID
    if rnd.random() < 0.6:
        lines.append(_make_line("INVOCATION_ID", _rand_invocation_id(rnd)))

    return lines

def _pick_extra_lines(rnd: random.Random) -> List[str]:
    lines: List[str] = []
    # Add a few extra metrics-like fields to vary content
    count = rnd.randint(0, 5)
    for _ in range(count):
        key = rnd.choice(_EXTRA_KEYS)
        if key == "STATUS":
            val = _rand_status(rnd)
        elif key.endswith("WEIGHT") or key.endswith("CURRENT") or key.endswith("PEAK"):
            val = _rand_decimal(rnd, 1, 1_000_000)
        else:
            val = _rand_decimal(rnd, 0, 1_000_000)
        lines.append(_make_line(key, val))
    return lines

def _shuffled(lines: List[str], rnd: random.Random) -> List[str]:
    rnd.shuffle(lines)
    return lines

def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    lines: List[str] = []
    lines += _pick_base_lines(rnd)
    lines += _pick_extra_lines(rnd)

    # Optionally duplicate STATUS with different content to match sd_notifyf style
    if rnd.random() < 0.5:
        lines.append(_make_line("STATUS", _rand_status(rnd)))

    # Shuffle order to vary execution paths
    lines = _shuffled(lines, rnd)

    # Ensure we always end with a newline; library expects NUL-terminated C-string
    blob = ''.join(lines)

    # Trim to safe size
    if len(blob) > _MAX_BYTES:
        blob = blob[:_MAX_BYTES]
        # Ensure last line ends with newline
        if not blob.endswith('\n'):
            last_nl = blob.rfind('\n')
            if last_nl == -1:
                blob = ''
            else:
                blob = blob[:last_nl+1]

    return blob.encode('ascii', errors='ignore')

import os
import random
import string
from typing import List

# Target data type: free-form text (C NUL-terminated strings without embedded NUL)
# This generator crafts a corpus-friendly mixture of strings suitable for:
# - systemd journal FIELD=value pairs (MESSAGE=, CODE_FILE=, CODE_LINE=, etc.)
# - D-Bus message signatures, object paths, interface/member/property names
# - sd-bus error names (bus-style dotted names)
# - sd-json keys/values, including typical JSON snippets
# - varlink interface/method names and IDL snippets
# - udev subsystem/sysname, properties, tags, sysattrs, modaliases
# - sd-path lookup suffixes
# The fuzzer framework will slice the buffer to feed multiple FUZZ_PARAM_STR() calls.

MAX_TOTAL = 4096

def _rand(rng: random.Random, lo: int, hi: int) -> int:
    return rng.randint(lo, hi)

def _pick(rng: random.Random, arr: List[str]) -> str:
    return arr[rng.randrange(len(arr))]

# Builders for various domains

def build_syslog_prefix(rng: random.Random) -> str:
    return _pick(rng, ["<0>", "<1>", "<2>", "<3>", "<4>", "<5>", "<6>", "<7>"])

def build_field_value(rng: random.Random, key: str = None) -> str:
    if key is None:
        key = _pick(rng, [
            "MESSAGE", "PRIORITY", "CODE_FILE", "CODE_LINE", "CODE_FUNC",
            "SYSLOG_IDENTIFIER", "UNIT", "OBJECT_PATH", "INTERFACE", "MEMBER"
        ])
    # value choices
    choice = _rand(rng, 0, 4)
    if choice == 0:
        val = build_human_text(rng)
    elif choice == 1:
        val = str(_rand(rng, 0, 200000))
    elif choice == 2:
        val = build_path(rng)
    elif choice == 3:
        val = build_bus_name(rng)
    else:
        val = build_identifier(rng)
    return f"{key}={val}"

def build_human_text(rng: random.Random) -> str:
    words = [
        "hello", "world", "systemd", "sd-bus", "journal", "udev", "varlink",
        "event", "json", "variant", "property", "error", "warning", "info"
    ]
    n = _rand(rng, 1, 10)
    return " ".join(_pick(rng, words) for _ in range(n))

def build_bus_name(rng: random.Random) -> str:
    # D-Bus error or interface name, e.g., org.example.Service.Error
    parts = []
    segs = _rand(rng, 2, 5)
    for _ in range(segs):
        l = _rand(rng, 1, 12)
        s = rng.choice(string.ascii_letters)
        s += ''.join(rng.choice(string.ascii_letters + string.digits + '_') for _ in range(l-1))
        parts.append(s)
    return ".".join(parts)

def build_object_path(rng: random.Random) -> str:
    # D-Bus object path
    segs = _rand(rng, 1, 6)
    seglist = []
    for _ in range(segs):
        l = _rand(rng, 1, 12)
        seg = ''.join(rng.choice(string.ascii_letters + string.digits + '_') for _ in range(l))
        seglist.append(seg)
    return "/" + "/".join(seglist)

def build_member(rng: random.Random) -> str:
    l = _rand(rng, 1, 16)
    return ''.join(rng.choice(string.ascii_letters + string.digits + '_') for _ in range(l))

def build_signature(rng: random.Random) -> str:
    # sd-bus type signatures (simple combos)
    atoms = ['i', 's', 't', 'b', 'd', 'y', 'o', 'g']
    n = _rand(rng, 0, 4)
    return ''.join(rng.choice(atoms) for _ in range(n))

def build_json_key(rng: random.Random) -> str:
    l = _rand(rng, 1, 12)
    start = rng.choice(string.ascii_letters + '_')
    rest = ''.join(rng.choice(string.ascii_letters + string.digits + '_-') for _ in range(l-1))
    return start + rest

def build_json_snippet(rng: random.Random) -> str:
    mode = _rand(rng, 0, 3)
    if mode == 0:
        # object with 1-3 pairs
        n = _rand(rng, 1, 3)
        pairs = []
        for _ in range(n):
            k = build_json_key(rng)
            vmode = _rand(rng, 0, 4)
            if vmode == 0:
                v = f'"{build_human_text(rng)}"'
            elif vmode == 1:
                v = str(_rand(rng, -1000, 100000))
            elif vmode == 2:
                v = str(rng.choice([True, False])).lower()
            elif vmode == 3:
                v = 'null'
            else:
                v = f'[{", ".join(str(_rand(rng, 0, 10)) for _ in range(_rand(rng,1,4)))}]'
            pairs.append(f'"{k}": {v}')
        return '{' + ', '.join(pairs) + '}'
    elif mode == 1:
        # array of strings
        n = _rand(rng, 0, 4)
        arr = ', '.join('"' + build_human_text(rng) + '"' for _ in range(n))
        return '[' + arr + ']'
    elif mode == 2:
        return 'null'
    else:
        return '"' + build_human_text(rng) + '"'

def build_varlink_idl(rng: random.Random) -> str:
    # Minimal varlink IDL snippet
    iface = build_bus_name(rng).replace('.', '.')
    mname = build_member(rng)
    fields_in = [f'{build_json_key(rng)}: string', f'{build_json_key(rng)}: int']
    fields_out = [f'{build_json_key(rng)}: string']
    return f"interface {iface}\nmethod {mname}({', '.join(fields_in)}) -> ({', '.join(fields_out)})\n"

def build_identifier(rng: random.Random) -> str:
    l = _rand(rng, 3, 20)
    start = rng.choice(string.ascii_letters + '_')
    rest = ''.join(rng.choice(string.ascii_letters + string.digits + '_-.') for _ in range(l-1))
    return start + rest

def build_path(rng: random.Random) -> str:
    # Generic filesystem-like path
    segs = _rand(rng, 1, 5)
    seglist = []
    for _ in range(segs):
        l = _rand(rng, 1, 10)
        seg = ''.join(rng.choice(string.ascii_letters + string.digits + '._-') for _ in range(l))
        seglist.append(seg)
    return "/" + "/".join(seglist)

def build_modalias(rng: random.Random) -> str:
    # Typical udev modalias patterns
    patterns = [
        "pci:v{vid:04X}d{did:04X}sv{sv:04X}sd{sd:04X}bc{bc:02X}sc{sc:02X}i{pi:02X}",
        "usb:v{vid:04X}p{pid:04X}d{rev:04X}",
        "platform:{name}",
        "acpi:{name}",
    ]
    p = _pick(rng, patterns)
    if "pci:" in p:
        return p.format(vid=_rand(rng,0,0xFFFF), did=_rand(rng,0,0xFFFF), sv=_rand(rng,0,0xFFFF), sd=_rand(rng,0,0xFFFF), bc=_rand(rng,0,0xFF), sc=_rand(rng,0,0xFF), pi=_rand(rng,0,0xFF))
    if "usb:" in p:
        return p.format(vid=_rand(rng,0,0xFFFF), pid=_rand(rng,0,0xFFFF), rev=_rand(rng,0,0xFFFF))
    name = build_identifier(rng)
    return p.format(name=name)

def build_seat(rng: random.Random) -> str:
    return _pick(rng, ["seat0", "seat1", "seat-gfx", "seat-remote"]) if _rand(rng,0,1) else ("seat" + str(_rand(rng,0,9)))

def build_session(rng: random.Random) -> str:
    return _pick(rng, ["c1", "tty1", "auto", "remote", "graphical"]) + str(_rand(rng,0,9999))

def build_udev_key(rng: random.Random) -> str:
    return _pick(rng, ["ID_MODEL", "ID_VENDOR", "ID_SERIAL", "SUBSYSTEM", "DEVTYPE", "DRIVER", "TAGS"]) + ("_" + build_identifier(rng) if _rand(rng,0,3)==0 else "")

def build_error_name(rng: random.Random) -> str:
    # sd-bus error names typically like org.freedesktop.DBus.Error.Failed
    base = _pick(rng, ["org.freedesktop", "com.example", "io.systemd", "org.example"])
    leaf = _pick(rng, ["Failed", "InvalidArgs", "NoMemory", "AccessDenied", "Timeout", "NotSupported"]) if _rand(rng,0,1) else build_member(rng).title()
    return base + ".Error." + leaf

def chunk_join(parts: List[str]) -> bytes:
    # Join with NUL separators so the harness can slice safely; avoid embedded NUL inside items
    return b"\0".join(s.encode('utf-8', 'ignore') for s in parts if s is not None) + b"\0"


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    parts: List[str] = []

    # Mix of general-purpose strings first (journal + sd-bus + json)
    parts.append(build_human_text(rng))
    parts.append(build_field_value(rng, "MESSAGE"))
    parts.append(build_field_value(rng, "CODE_FILE"))
    parts.append("CODE_LINE=" + str(_rand(rng, 1, 200000)))
    parts.append("CODE_FUNC=fuzz_entry")
    parts.append(build_syslog_prefix(rng))

    # sd-bus related
    parts.append(build_object_path(rng))
    parts.append(build_bus_name(rng))  # interface
    parts.append(build_member(rng))    # member/property
    parts.append(build_signature(rng))
    parts.append(build_error_name(rng))

    # sd-json keys/values and snippets
    for _ in range(_rand(rng, 1, 3)):
        parts.append(build_json_key(rng))
        parts.append(build_human_text(rng))
    parts.append(build_json_snippet(rng))

    # varlink
    parts.append(build_varlink_idl(rng))
    parts.append(build_member(rng))  # method name

    # sd-path suffix candidates
    parts.append(build_path(rng))
    parts.append("")  # allow NULL-equivalent for optional suffix when split

    # sd-login / sessions / seats
    parts.append(build_seat(rng))
    parts.append(build_session(rng))

    # udev subsystem/sysname/properties/tags/sysattrs/modalias
    parts.append(_pick(rng, ["block", "net", "tty", "input", "usb", "pci"]))
    parts.append(build_member(rng))  # sysname-like
    parts.append(build_udev_key(rng))
    parts.append(build_identifier(rng))  # property value
    parts.append(_pick(rng, ["uaccess", "seat", "systemd", "graphics", "sound"]))
    parts.append(build_modalias(rng))
    parts.append(_pick(rng, ["DEVNAME", "DEVPATH", "ID_MODEL", "ID_VENDOR"]))
    parts.append(build_identifier(rng))

    # sd-hwdb key lookup
    parts.append(build_modalias(rng))
    parts.append(build_udev_key(rng))

    # Varlink addresses/URLs/names
    parts.append(_pick(rng, [
        "unix:/run/io.systemd.Service",
        "tcp:127.0.0.1:7070",
        "fd:3",
        "exec:/usr/bin/true",
        "stdio"
    ]))
    parts.append(_pick(rng, [
        "io.systemd.Example",
        "com.example.Tool",
        "org.freedesktop.DBus"
    ]))

    # Additional general strings to satisfy multiple FUZZ_PARAM_STR consumers
    for _ in range(_rand(rng, 10, 20)):
        choice = _rand(rng, 0, 8)
        if choice == 0:
            parts.append(build_human_text(rng))
        elif choice == 1:
            parts.append(build_bus_name(rng))
        elif choice == 2:
            parts.append(build_object_path(rng))
        elif choice == 3:
            parts.append(build_member(rng))
        elif choice == 4:
            parts.append(build_signature(rng))
        elif choice == 5:
            parts.append(build_json_snippet(rng))
        elif choice == 6:
            parts.append(build_field_value(rng))
        else:
            parts.append(build_identifier(rng))

    blob = chunk_join(parts)
    if len(blob) > MAX_TOTAL:
        blob = blob[:MAX_TOTAL]
        # ensure final byte is NUL to properly terminate last string
        blob = blob[:-1] + b"\0"
    return blob

import random
from typing import List

# Generator for: memory pressure type string
# Context: sd_event_source_set_memory_pressure_type expects a C-string naming a valid
# memory pressure category. systemd commonly uses identifiers like: low, medium,
# critical, reclaim, memcg, psi-* levels, etc. We generate a variety of plausible,
# NUL-terminated ASCII tokens, sometimes with namespace prefixes that systemd code
# often accepts (e.g., "auto", "default", "off", and PSI-style levels).

_VALID_BASE_TYPES: List[str] = [
    # Common severity/level style
    "low", "medium", "high", "critical", "urgent",
    # Linux PSI-inspired pressure levels
    "some", "full",
    # Memory pressure / reclaim related
    "reclaim", "oom", "oom-kill", "swap", "swaplow", "swaphigh",
    # Typical toggles/defaults that many sd-apis accept
    "default", "auto", "off", "on",
    # cgroup/memory controller related
    "memcg", "cgroup", "cgpressure",
    # Additional variants
    "background", "foreground", "idle", "burst",
]

_PREFIXES: List[str] = [
    "psi:", "mem:", "memory:", "vm:", "system:", "kernel:", "user:",
]

_SUFFIXES: List[str] = [
    ":some", ":full", ":low", ":medium", ":high", ":critical",
]

# Some composite named configurations that might be recognized by implementations
_COMPOSITES: List[str] = [
    "psi:mem:some", "psi:mem:full", "memory:pressure:low", "memory:pressure:high",
    "mem:reclaim", "kernel:oom", "system:swap:high", "vm:pressure:medium",
]

# Ensure ASCII token characters only
_CHARS = "abcdefghijklmnopqrstuvwxyz0123456789:_-"


def _rand_token(rng: random.Random, min_len: int = 2, max_len: int = 24) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(_CHARS) for _ in range(n))


def _build_candidate(rng: random.Random) -> str:
    # Choose among patterns to cover breadth
    choice = rng.random()
    if choice < 0.25:
        # Simple known base
        return rng.choice(_VALID_BASE_TYPES)
    elif choice < 0.45:
        # Prefixed known base
        return rng.choice(_PREFIXES) + rng.choice(_VALID_BASE_TYPES)
    elif choice < 0.6:
        # Known base with suffix qualifier
        return rng.choice(_VALID_BASE_TYPES) + rng.choice(_SUFFIXES)
    elif choice < 0.75:
        # Composite known pattern
        return rng.choice(_COMPOSITES)
    elif choice < 0.9:
        # Random token, possibly with prefix or suffix
        base = _rand_token(rng)
        if rng.random() < 0.5:
            base = rng.choice(_PREFIXES) + base
        if rng.random() < 0.5:
            base = base + rng.choice(_SUFFIXES)
        return base
    else:
        # Join a couple of base tokens with separators common in identifiers
        parts = [rng.choice(_VALID_BASE_TYPES)]
        if rng.random() < 0.7:
            parts.append(rng.choice(_VALID_BASE_TYPES))
        sep = ':' if rng.random() < 0.5 else '-'
        return sep.join(parts)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Produce a plausible, NUL-terminated C string.
    token = _build_candidate(rng)

    # Guarantee non-empty, ASCII, <= 4096 bytes, and NUL-terminated
    if not token:
        token = "default"

    # Limit to reasonable length
    token = token[:1023]

    # Return as bytes with trailing NUL to match C-string expectations
    return (token + "\x00").encode("ascii", errors="ignore")

import random
import string
from typing import List

# Target data type: printf format string
# Usage in stubs always passes exactly one %s (and sometimes a FIELD= prefix like MESSAGE=%s).
# We should generate interesting, valid, NUL-terminated strings that are safe printf formats
# compatible with the stubs' expectations. Since stubs hardcode the format themselves,
# our FUZZ_PARAM_STR content becomes the single %s argument. Therefore, generate strings
# that are valid as message payloads and journal FIELD=value content. Focus on:
# - ASCII, UTF-8 with multibyte sequences
# - Different lengths, including empty and near-limit
# - Embedded newlines, NUL-free
# - Key/value like ENV=, CODE_*, PRIORITY= patterns
# - JSON, UUID-like, hex, base64-like
# - syslog-like prefixes <0>.. <7>
# Ensure size <= 4096 bytes.

MAX_LEN = 4096

SYSLOG_PREFIXES = [f"<{i}>" for i in range(8)]

CONTROL_CHARS = "\t\n\r\v\f"
PRINTABLE = string.ascii_letters + string.digits + string.punctuation + " "

# Some interesting unicode snippets (valid UTF-8)
UNICODE_SNIPPETS = [
    "Привет",  # Cyrillic
    "こんにちは",  # Japanese
    "😊🚀",       # Emoji
    "𝔘𝔫𝔦𝔠𝔬𝔡𝔢",    # Fraktur
    "مرحبا",      # Arabic
    "Καλημέρα",   # Greek
]

UUIDS = [
    "00000000-0000-0000-0000-000000000000",
    "123e4567-e89b-12d3-a456-426614174000",
    "ffffffff-ffff-ffff-ffff-ffffffffffff",
]

HEX_SAMPLES = [
    "deadbeef",
    "CAFEBABE",
    "0123456789abcdef",
]

BASE64_SAMPLES = [
    "SGVsbG8sIFdvcmxkIQ==",
    "AAECAwQFBgcICQ==",
    "8J+YgPCfk4E=",  # emoji in utf-8 base64
]

JSON_SAMPLES = [
    "{}",
    "{\"message\":\"hello\"}",
    "{\"a\":1,\"b\":[true,false,null],\"s\":\"x\"}",
]

KV_KEYS = [
    "MESSAGE", "PRIORITY", "CODE_FILE", "CODE_LINE", "CODE_FUNC",
    "SYSLOG_IDENTIFIER", "UNIT", "OBJECT_PATH", "ERRNO", "USER_ID",
]


def _rand(r: random.Random, seq: List[str]):
    return seq[r.randrange(len(seq))]


def rand_ascii(r: random.Random, n: int) -> str:
    return ''.join(r.choice(PRINTABLE) for _ in range(n))


def rand_mixed_text(r: random.Random, target_len: int) -> str:
    parts: List[str] = []
    while sum(len(p) for p in parts) < target_len:
        choice = r.randrange(6)
        if choice == 0:
            parts.append(rand_ascii(r, r.randint(1, 32)))
        elif choice == 1:
            parts.append(_rand(r, UNICODE_SNIPPETS))
        elif choice == 2:
            parts.append(_rand(r, SYSLOG_PREFIXES))
        elif choice == 3:
            parts.append(r.choice(CONTROL_CHARS) * r.randint(1, 3))
        elif choice == 4:
            parts.append(_rand(r, JSON_SAMPLES))
        else:
            parts.append(_rand(r, UUIDS))
    s = ''.join(parts)
    if len(s) > target_len:
        s = s[:target_len]
    return s


def make_kv(r: random.Random) -> str:
    key = _rand(r, KV_KEYS)
    # random value flavor
    t = r.randrange(7)
    if t == 0:
        val = _rand(r, UUIDS)
    elif t == 1:
        val = _rand(r, HEX_SAMPLES)
    elif t == 2:
        val = _rand(r, BASE64_SAMPLES)
    elif t == 3:
        val = str(r.randint(0, 1000000))
    elif t == 4:
        val = _rand(r, UNICODE_SNIPPETS)
    elif t == 5:
        val = _rand(r, JSON_SAMPLES)
    else:
        val = rand_ascii(r, r.randint(1, 40))
    return f"{key}={val}"


def assemble_payload(r: random.Random) -> str:
    # choose a scenario
    scenario = r.randrange(8)
    if scenario == 0:
        # simple short message
        return _rand(r, ["", "ok", "hello", "test", "a" * r.randint(1, 64)])
    if scenario == 1:
        # syslog-like prefix + message
        return _rand(r, SYSLOG_PREFIXES) + rand_mixed_text(r, r.randint(5, 200))
    if scenario == 2:
        # KV line suitable for sd_journal_send MESSAGE field already provided by stub
        # but it's fine as arbitrary content for %s
        return make_kv(r)
    if scenario == 3:
        # multiple lines
        lines = [make_kv(r) for _ in range(r.randint(2, 6))]
        return "\n".join(lines)
    if scenario == 4:
        # JSON blob
        return _rand(r, JSON_SAMPLES)
    if scenario == 5:
        # Long mixed text, within limit
        return rand_mixed_text(r, r.randint(50, 800))
    if scenario == 6:
        # UUID or id128-like hex without dashes
        return r.choice([_rand(r, UUIDS), _rand(r, HEX_SAMPLES)*r.randint(1, 4)])
    # scenario 7
    # Structured journal-like pairs (even though stub uses MESSAGE=%s, content is free-form)
    fields = [
        f"SYSLOG_IDENTIFIER={rand_ascii(r, r.randint(3,12))}",
        f"PRIORITY={r.randint(0,7)}",
        f"CODE_FILE=fuzz_stub.cc",
        f"CODE_LINE={r.randint(1, 100000)}",
        f"CODE_FUNC=fuzz_entry",
        f"MESSAGE={rand_mixed_text(r, r.randint(5, 60))}",
    ]
    return "\n".join(fields)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    payload = assemble_payload(r)
    # Ensure overall size limit and no embedded NULs (we never introduce NULs)
    b = payload.encode('utf-8', errors='strict')
    if len(b) > MAX_LEN:
        b = b[:MAX_LEN]
        # Avoid splitting a multibyte sequence: backtrack to valid UTF-8 boundary
        # Try decoding progressively shorter suffix until valid
        for cut in range(0, 4):
            try:
                _ = b[:-cut] if cut else b
                (_).decode('utf-8')
                b = _
                break
            except UnicodeDecodeError:
                continue
    return b

import random
import string
from typing import List, Tuple

# Generator for D-Bus address strings (NUL-terminated expected by C as const char*)
# Focus: valid, interesting transport/address combinations per D-Bus spec
# Formats covered:
# - unix:path=...
# - unix:abstract=...
# - unix:tmpdir=...,guid=...
# - tcp:host=...,port=...,family=ipv4/ipv6,bind=...,listen=true
# - autolaunch:guid=...
# - unixexec:path=...,argvN=...
# - nonce-tcp:host=...,port=...,noncefile=...
# - multiple addresses separated by ','
# - randomized key ordering and optional flags

HEX = '0123456789abcdef'
BASE36 = string.digits + string.ascii_lowercase


def _rand_hex(r: random.Random, n: int) -> str:
    return ''.join(r.choice(HEX) for _ in range(n))


def _rand_base36(r: random.Random, n: int) -> str:
    return ''.join(r.choice(BASE36) for _ in range(n))


def _rand_hostname(r: random.Random) -> str:
    labels = []
    for _ in range(r.randint(1, 3)):
        ln = r.randint(1, 10)
        s = ''.join(r.choice(string.ascii_lowercase + string.digits) for _ in range(ln))
        if r.random() < 0.3 and ln > 1:
            pos = r.randint(1, ln - 1)
            s = s[:pos] + '-' + s[pos:]
        labels.append(s)
    return '.'.join(labels)


def _rand_ipv4(r: random.Random) -> str:
    return '.'.join(str(r.randint(1, 254)) for _ in range(4))


def _rand_ipv6(r: random.Random) -> str:
    # Return a valid IPv6 string, possibly compressed
    if r.random() < 0.5:
        return ':'.join(_rand_hex(r, 4) for _ in range(8))
    left = r.randint(1, 5)
    right = r.randint(1, 5)
    left_part = ':'.join(_rand_hex(r, 4) for _ in range(left))
    right_part = ':'.join(_rand_hex(r, 4) for _ in range(right))
    # Build manually to avoid f-string format-spec pitfalls with ':'
    if right == 0:
        return left_part + '::'
    else:
        return left_part + '::' + right_part


def _rand_port(r: random.Random) -> str:
    picks = ["80", "443", "5000", "5555", "664", str(r.randint(1, 65535))]
    return r.choice(picks)


def _rand_path(r: random.Random) -> str:
    prefixes = [
        "/run/user/%d/bus" % r.randint(0, 60000),
        "/run/dbus/system_bus_socket",
        "/tmp/dbus-%s" % _rand_base36(r, r.randint(6, 12)),
        "/var/run/dbus/system_bus_socket",
        "/home/%s/.dbus/socket" % _rand_base36(r, r.randint(3, 8)),
    ]
    if r.random() < 0.4:
        depth = r.randint(1, 3)
        for _ in range(depth):
            prefixes.append(prefixes[-1] + "/" + _rand_base36(r, r.randint(3, 8)))
    return r.choice(prefixes)


def _rand_guid(r: random.Random) -> str:
    # D-Bus GUID is 32 lowercase hex chars
    return _rand_hex(r, 32)


def _kv_join(items: List[Tuple[str, str]]) -> str:
    return ','.join(f"{k}={v}" for k, v in items)


def _unix_addr(r: random.Random) -> str:
    variants: List[Tuple[str, str]] = []
    choice = r.random()
    if choice < 0.4:
        variants.append(("path", _rand_path(r)))
    elif choice < 0.8:
        name = "dbus-" + _rand_base36(r, r.randint(6, 16))
        variants.append(("abstract", name))
    else:
        variants.append(("tmpdir", "/tmp"))
        if r.random() < 0.7:
            variants.append(("guid", _rand_guid(r)))
    if r.random() < 0.3:
        variants.append(("listen", "true" if r.random() < 0.5 else "false"))
    r.shuffle(variants)
    return "unix:" + _kv_join(variants)


def _tcp_addr(r: random.Random, nonce: bool = False) -> str:
    host_sel = r.random()
    if host_sel < 0.33:
        host = _rand_hostname(r)
    elif host_sel < 0.66:
        host = _rand_ipv4(r)
    else:
        host = "[" + _rand_ipv6(r) + "]"  # bracketed IPv6

    items: List[Tuple[str, str]] = [("host", host), ("port", _rand_port(r))]
    fam = r.choice(["ipv4", "ipv6"]) if r.random() < 0.5 else None
    if fam:
        items.append(("family", fam))
    if r.random() < 0.3:
        items.append(("bind", _rand_ipv4(r)))
    if r.random() < 0.3:
        items.append(("listen", "true" if r.random() < 0.5 else "false"))
    if r.random() < 0.3:
        items.append(("guid", _rand_guid(r)))
    if nonce:
        items.append(("noncefile", "/tmp/nonce-" + _rand_base36(r, 10)))
    r.shuffle(items)
    prefix = "nonce-tcp:" if nonce else "tcp:"
    return prefix + _kv_join(items)


def _autolaunch_addr(r: random.Random) -> str:
    items: List[Tuple[str, str]] = []
    if r.random() < 0.8:
        items.append(("guid", _rand_guid(r)))
    if r.random() < 0.4:
        items.append(("display", ":%d" % r.randint(0, 99)))
    if r.random() < 0.3:
        items.append(("scope", r.choice(["user", "system"])))
    r.shuffle(items)
    return "autolaunch:" + _kv_join(items) if items else "autolaunch:"


def _unixexec_addr(r: random.Random) -> str:
    path = r.choice([
        "/bin/dbus-proxy",
        "/usr/bin/dbus-broker-launch",
        "/usr/bin/env",
        "/bin/sh",
    ])
    items: List[Tuple[str, str]] = [("path", path)]
    argc = r.randint(0, 4)
    for i in range(argc):
        val = r.choice([
            "--session",
            "--system",
            "--address=unix:path=/run/user/%d/bus" % r.randint(0, 60000),
            "-c",
            "echo",
        ])
        items.append((f"argv{i}", val))
    r.shuffle(items)
    return "unixexec:" + _kv_join(items)


def _one_address(r: random.Random) -> str:
    pick = r.random()
    if pick < 0.35:
        return _unix_addr(r)
    if pick < 0.60:
        return _tcp_addr(r)
    if pick < 0.70:
        return _tcp_addr(r, nonce=True)
    if pick < 0.85:
        return _autolaunch_addr(r)
    return _unixexec_addr(r)


def _multi_address(r: random.Random) -> str:
    n = r.randint(2, 4)
    return ','.join(_one_address(r) for _ in range(n))


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    if r.random() < 0.6:
        addr = _one_address(r)
    else:
        addr = _multi_address(r)

    if r.random() < 0.3:
        addr = addr.replace(",", ", ")

    addr = addr[:4000]
    return addr.encode("utf-8", errors="strict")

import random
import string
from typing import List, Tuple

# Generator for D-Bus match rules (NUL-terminated text). Target: sd_bus_add_match(_async)
# We aim to produce syntactically valid rules covering various keys, quoting, booleans,
# and multiple comma-separated terms.

_DBUS_TYPES = [
    "signal", "method_call", "method_return", "error"
]

# Some reasonable buses/interfaces/members/paths/senders
_IFACES = [
    "org.freedesktop.DBus", "org.freedesktop.login1.Manager",
    "org.freedesktop.systemd1.Manager", "org.example.Demo",
    "com.example.App", "org.a.b.c"
]
_MEMBERS = [
    "NameOwnerChanged", "JobRemoved", "UnitNew", "PropertiesChanged",
    "Ping", "Hello", "Notify", "Bar", "Baz"
]
_PATHS = [
    "/org/freedesktop/DBus", "/org/freedesktop/login1",
    "/org/freedesktop/systemd1", "/org/example/Demo",
    "/", "/a/b/c"
]
_SENDERS = [
    "org.freedesktop.DBus", "org.freedesktop.systemd1",
    "org.freedesktop.login1", "org.example.Service", "com.example.App"
]
_DESTS = [
    "org.freedesktop.DBus", "org.freedesktop.systemd1", "org.example.Service"
]

# argN values: strings likely to appear in payloads
_ARG_VALUES = [
    "", "0", "1", "true", "false", "READY=1", "Hello", "世界", "αβγ",
    "foo", "bar", "org.example.Object", "/x/y/z"
]

# Utilities

def _rand_bool(r: random.Random) -> bool:
    return bool(r.getrandbits(1))


def _pick(r: random.Random, seq: List[str]) -> str:
    return seq[r.randrange(len(seq))]


def _rand_ident(r: random.Random, prefix: str = "org") -> str:
    # Generate a dotted bus name-like identifier
    parts = [prefix]
    n = r.randint(1, 4)
    alpha = string.ascii_letters
    alnum = string.ascii_letters + string.digits + "_"
    for _ in range(n):
        first = r.choice(alpha).lower()
        rest = ''.join(r.choice(alnum).lower() for _ in range(r.randint(2, 8)))
        parts.append(first + rest)
    return '.'.join(parts)


def _rand_path(r: random.Random) -> str:
    n = r.randint(0, 5)
    if n == 0:
        return "/"
    segchars = string.ascii_letters + string.digits + "_"
    segs = [''.join(r.choice(segchars) for _ in range(r.randint(1, 8))) for _ in range(n)]
    return "/" + "/".join(segs)


def _quote(s: str) -> str:
    # D-Bus match rules require single-quoted values; escape single quotes and backslashes
    s = s.replace('\\', r"\\").replace("'", r"\'")
    return "'" + s + "'"


def _kv(key: str, value: str) -> str:
    return f"{key}={_quote(value)}"


def _maybe(flags: List[Tuple[str, bool]]) -> List[str]:
    return [k for k, on in flags if on]


def _arg_terms(r: random.Random) -> List[str]:
    terms = []
    # Choose between argN exact and argNpath (prefix) terms
    count = r.randint(0, 3)
    for _ in range(count):
        n = r.randint(0, 7)
        if _rand_bool(r):
            terms.append(_kv(f"arg{n}", _pick(r, _ARG_VALUES)))
        else:
            # argNpath expects a path-like value
            terms.append(_kv(f"arg{n}path", _rand_path(r)))
    return terms


def _bus_specific_terms(r: random.Random) -> List[str]:
    terms = []
    # Common fields
    if _rand_bool(r):
        terms.append(_kv("type", _pick(r, _DBUS_TYPES)))
    if _rand_bool(r):
        terms.append(_kv("sender", _pick(r, _SENDERS) if _rand_bool(r) else _rand_ident(r)))
    if _rand_bool(r):
        terms.append(_kv("destination", _pick(r, _DESTS) if _rand_bool(r) else _rand_ident(r, "com")))
    if _rand_bool(r):
        terms.append(_kv("interface", _pick(r, _IFACES) if _rand_bool(r) else _rand_ident(r)))
    if _rand_bool(r):
        terms.append(_kv("member", _pick(r, _MEMBERS)))
    if _rand_bool(r):
        terms.append(_kv("path", _pick(r, _PATHS) if _rand_bool(r) else _rand_path(r)))
    # Boolean toggles: eavesdrop, path_namespace
    if _rand_bool(r):
        terms.append(_kv("eavesdrop", "true" if _rand_bool(r) else "false"))
    if _rand_bool(r):
        terms.append(_kv("path_namespace", "true" if _rand_bool(r) else "false"))
    return terms


def _priority_terms(r: random.Random) -> List[str]:
    # systemd sd-bus supports match rules with min/max priority extensions
    terms = []
    if _rand_bool(r):
        terms.append(_kv("min_priority", str(r.randint(-100, 100))))
    if _rand_bool(r):
        terms.append(_kv("max_priority", str(r.randint(-100, 100))))
    return terms


def _compose_rule(r: random.Random) -> str:
    # Build a comma-separated rule with random ordering
    parts: List[str] = []
    parts.extend(_bus_specific_terms(r))
    parts.extend(_arg_terms(r))
    parts.extend(_priority_terms(r))

    # Ensure at least one term; fall back to a very common rule
    if not parts:
        parts = [
            _kv("type", "signal"),
            _kv("interface", "org.freedesktop.DBus"),
            _kv("member", "NameOwnerChanged"),
        ]

    # Possibly add duplicates with different values to exercise last-wins behavior
    if _rand_bool(r):
        dup_key = r.choice(["type", "sender", "destination", "interface", "member", "path"])
        if dup_key == "type":
            parts.append(_kv("type", _pick(r, _DBUS_TYPES)))
        elif dup_key in ("sender", "destination", "interface"):
            parts.append(_kv(dup_key, _rand_ident(r)))
        elif dup_key == "member":
            parts.append(_kv("member", _pick(r, _MEMBERS)))
        else:
            parts.append(_kv("path", _rand_path(r)))

    r.shuffle(parts)
    return ",".join(parts)


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose to emit one rule or a sequence of rules separated by newlines. The fuzzer pulls
    # FUZZ_PARAM_STR arbitrarily; having multiple lines allows it to split if needed or use full string.
    lines = []
    line_count = r.randint(1, 4)
    for _ in range(line_count):
        rule = _compose_rule(r)
        # Keep each rule comfortably small; hard cap overall below 4096
        if len(rule) > 900:
            rule = rule[:900]
        lines.append(rule)

    payload = "\n".join(lines)

    # Ensure NUL-termination for C API expectations; FUZZ_PARAM_STR provides a std::string
    # but we return bytes here which the harness writes to a file/buffer. Include final NUL.
    b = payload.encode("utf-8") + b"\x00"

    # Cap to 4096 bytes
    if len(b) > 4096:
        b = b[:4095] + b"\x00"
    return b

import json
import random
import string
from typing import List

# Generator for valid JSON texts covering various structures and edge cases.
# Outputs a bytes buffer with multiple standalone JSON documents separated by
# newlines, terminated with a single NUL byte. Size <= 4096 bytes.

MAX_BYTES = 4096

ESCAPE_CHARS = ['\\"', "\\\\", "\\/", "\\b", "\\f", "\\n", "\\r", "\\t"]
# Avoid surrogate code points; include only valid, encodable characters.
UNICODE_SAMPLES = [
    "Ω", "€", "漢字", "🙂", "\u2603", "\u00A0",
]


def rnd_str(rng: random.Random, min_len: int, max_len: int) -> str:
    n = rng.randint(min_len, max_len)
    alphabet = string.ascii_letters + string.digits + " _-:.@/"
    s = ''.join(rng.choice(alphabet) for _ in range(n))
    # sprinkle escapes and unicode (avoid inserting raw NULs or surrogates)
    if n > 0:
        if rng.random() < 0.7:
            s += rng.choice(UNICODE_SAMPLES)
        if rng.random() < 0.7 and len(s) > 1:
            mid = max(1, len(s) // 2)
            s = s[:mid] + rng.choice(ESCAPE_CHARS) + s[mid:]
    return s


def rnd_number(rng: random.Random) -> float:
    choice = rng.random()
    if choice < 0.2:
        return 0
    if choice < 0.4:
        return -1
    if choice < 0.6:
        return rng.choice([2**31 - 1, -2**31, 2**53 - 1, -(2**53 - 1)])
    if choice < 0.8:
        return float(f"{rng.randint(-10**6, 10**6)}.{rng.randint(0, 999999):06d}")
    return float(f"{rng.choice([-1,1]) * rng.randint(1, 999)}e{rng.randint(-308, 308)}")


def rnd_scalar(rng: random.Random):
    t = rng.random()
    if t < 0.33:
        return rnd_number(rng)
    if t < 0.66:
        return rng.choice([True, False, None])
    return rnd_str(rng, 0, 16)


def rnd_array(rng: random.Random, depth: int) -> list:
    n = rng.randint(0, 8 if depth < 3 else 3)
    return [rnd_value(rng, depth + 1) for _ in range(n)]


def rnd_object(rng: random.Random, depth: int) -> dict:
    n = rng.randint(0, 8 if depth < 3 else 3)
    obj = {}
    for _ in range(n):
        key = rnd_str(rng, 1, 12)
        obj[key] = rnd_value(rng, depth + 1)
    return obj


def rnd_value(rng: random.Random, depth: int = 0):
    if depth > 6:
        return rnd_scalar(rng)
    t = rng.random()
    if t < 0.25:
        return rnd_scalar(rng)
    if t < 0.5:
        return rnd_array(rng, depth)
    return rnd_object(rng, depth)


def make_primary_json(rng: random.Random) -> str:
    p = rng.random()
    if p < 0.15:
        val = rnd_scalar(rng)
    elif p < 0.6:
        val = rnd_array(rng, 0)
    else:
        val = rnd_object(rng, 0)
    return json.dumps(val, ensure_ascii=False, separators=(",", ":"))


def canned_samples() -> List[str]:
    samples = [
        "null",
        "true",
        "false",
        "[]",
        "{}",
        "{\"a\":[1,2,3]}",
        "{\"k\":1}",
        json.dumps({"deep": {"nest": [1, {"x": [True, False, None, "s"]}, 3]}}, ensure_ascii=False),
        json.dumps([i for i in range(10)], separators=(",", ":")),
        json.dumps({"empty_array": [], "empty_obj": {}}, separators=(",", ":")),
        json.dumps({"min": -9007199254740991, "max": 9007199254740991}),
        json.dumps({"unicode": "Ω漢🙂\nline\t\u2603"}),
        json.dumps([{"a":1}, {"b":[2,3]}, 4, "s", True, None]),
    ]
    return samples


def assemble_buffer(parts: List[str]) -> bytes:
    joined = "\n".join(parts)
    # Strict UTF-8; all parts constructed without surrogates
    data = joined.encode("utf-8", errors="strict")
    # Truncate to leave room for trailing NUL
    if len(data) >= MAX_BYTES:
        data = data[: MAX_BYTES - 1]
        # Re-encode cleanly in case of multi-byte cut
        data = data.decode("utf-8", errors="ignore").encode("utf-8")
        if len(data) >= MAX_BYTES:
            data = data[: MAX_BYTES - 1]
    return data + b"\x00"


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    parts: List[str] = []

    samples = canned_samples()
    rng.shuffle(samples)
    keep = rng.randint(5, min(10, len(samples)))
    parts.extend(samples[:keep])

    parts.append(make_primary_json(rng))
    if rng.random() < 0.7:
        parts.append(make_primary_json(rng))

    # Include a small JSON that resembles a filename path to exercise code paths
    path_like = json.dumps({"file": "/tmp/" + rnd_str(rng, 3, 10) + ".json"})
    parts.append(path_like)

    return assemble_buffer(parts)
